import java.io.File;
import java.nio.file.Files;
import java.io.IOException;

/** Cleanup limited to the intermediate filenames generated by the program. */
public final class TemporaryDataFiles {
    private TemporaryDataFiles() { }

    public static void cleanupLeftovers() {
        File[] files = new File(".").listFiles();
        if (files == null) {
            System.err.println("Unable to list temporary data files.");
            return;
        }
        for (File file : files) {
            if (file.isFile() && file.getName().matches(
                    "(?:data[0-9]*\\.arff|data_temp[0-9]*\\.csv|(?:test|train)_temp\\.csv)")) {
                delete(file);
            }
        }
    }

    public static void cleanupFold(long index) {
        delete(new File("data_temp" + index + ".csv"));
        delete(new File("data" + index + ".arff"));
    }

    private static void delete(File file) {
        try {
            Files.deleteIfExists(file.toPath());
        } catch (IOException e) {
            System.err.println("Unable to delete temporary file " + file + ": " + e.getMessage());
            file.deleteOnExit();
        }
    }
}
